     1→package config
     2→
     3→import (
     4→	"errors"
     5→	"fmt"
     6→	"log/slog"
     7→	"maps"
     8→	"os"
     9→	"regexp"
    10→	"slices"
    11→	"strings"
    12→
    13→	"gopkg.in/yaml.v3"
    14→)
    15→
    16→type Config struct {
    17→	Server Server            `yaml:"server"          json:"server"`
    18→	Apps   map[string]App    `yaml:"apps,omitempty"  json:"apps,omitempty"`
    19→	Stacks map[string]Stack  `yaml:"stacks,omitempty" json:"stacks,omitempty"`
    20→}
    21→
    22→type Server struct {
    23→	Name         string `yaml:"name"          json:"name"`
    24→	DeployDomain string `yaml:"deploy_domain" json:"deploy_domain"`
    25→	StacksDir    string `yaml:"stacks_dir"    json:"stacks_dir"`
    26→	GithubToken  string `yaml:"github_token"  json:"github_token,omitempty"`
    27→	AcmeEmail    string `yaml:"acme_email"    json:"acme_email,omitempty"`
    28→}
    29→
    30→type App struct {
    31→	Repo     string         `yaml:"repo"              json:"repo"`
    32→	Branch   string         `yaml:"branch"            json:"branch"`
    33→	Domain   string         `yaml:"domain"            json:"domain"`
    34→	EnvFile  string         `yaml:"env_file,omitempty"  json:"env_file,omitzero"`
    35→	Compose  string         `yaml:"compose,omitempty"   json:"compose,omitzero"`
    36→	Override string         `yaml:"override,omitempty"  json:"override,omitzero"`
    37→	Secrets  []SecretRef    `yaml:"secrets,omitempty"   json:"secrets,omitzero"`
    38→	Preview  *PreviewConfig `yaml:"preview,omitempty"   json:"preview,omitzero"`
    39→}
    40→
    41→type Stack struct {
    42→	Path         string `yaml:"path"                    json:"path"`
    43→	Domain       string `yaml:"domain"                  json:"domain"`
    44→	AutoDeploy   bool   `yaml:"auto_deploy"             json:"auto_deploy,omitzero"`
    45→	UpdateScript string `yaml:"update_script,omitempty" json:"update_script,omitzero"`
    46→}
    47→
    48→type SecretRef struct {
    49→	Key    string `yaml:"key"    json:"key"`
    50→	Type   string `yaml:"type"   json:"type"`
    51→	Target string `yaml:"target" json:"target"`
    52→}
    53→
    54→type PreviewConfig struct {
    55→	Enabled bool   `yaml:"enabled"           json:"enabled,omitzero"`
    56→	Domain  string `yaml:"domain,omitempty"  json:"domain,omitzero"`
    57→}
    58→
    59→var envVarRe = regexp.MustCompile(`\$\{([^}]+)\}`)
    60→
    61→// Load reads the YAML config file at path, applies defaults, expands env vars,
    62→// and validates the result. Returns a descriptive error on any failure.
    63→func Load(path string) (*Config, error) {
    64→	data, err := os.ReadFile(path)
    65→	if err != nil {
    66→		return nil, fmt.Errorf("reading config %s: %w", path, err)
    67→	}
    68→
    69→	var cfg Config
    70→	if err := yaml.Unmarshal(data, &cfg); err != nil {
    71→		var typeErr *yaml.TypeError
    72→		if errors.As(err, &typeErr) {
    73→			return nil, fmt.Errorf("config %s: %w", path, typeErr)
    74→		}
    75→		return nil, fmt.Errorf("config %s: %w", path, err)
    76→	}
    77→
    78→	// Expand ${VAR} in github_token only.
    79→	original := cfg.Server.GithubToken
    80→	cfg.Server.GithubToken = envVarRe.ReplaceAllStringFunc(cfg.Server.GithubToken, func(match string) string {
    81→		varName := match[2 : len(match)-1]
    82→		return os.Getenv(varName)
    83→	})
    84→	if cfg.Server.GithubToken == "" && strings.Contains(original, "${") {
    85→		slog.Warn("github_token expanded to empty string", "original", original)
    86→	}
    87→
    88→	// Default acme_email to webmaster@<deploy_domain>.
    89→	if cfg.Server.AcmeEmail == "" && cfg.Server.DeployDomain != "" {
    90→		cfg.Server.AcmeEmail = "webmaster@" + cfg.Server.DeployDomain
    91→	}
    92→
    93→	// Apply defaults for app fields.
    94→	for name, app := range cfg.Apps {
    95→		if app.Branch == "" {
    96→			app.Branch = "main"
    97→		}
    98→		if app.Compose == "" {
    99→			app.Compose = "compose.yml"
   100→		}
   101→		cfg.Apps[name] = app
   102→	}
   103→
   104→	if err := validate(&cfg); err != nil {
   105→		return nil, err
   106→	}
   107→
   108→	return &cfg, nil
   109→}
   110→
   111→func validate(cfg *Config) error {
   112→	if cfg.Server.Name == "" {
   113→		return errors.New("server.name is required")
   114→	}
   115→	if cfg.Server.DeployDomain == "" {
   116→		return errors.New("server.deploy_domain is required")
   117→	}
   118→	if cfg.Server.StacksDir == "" {
   119→		return errors.New("server.stacks_dir is required")
   120→	}
   121→
   122→	// Collect all domains to detect duplicates across apps and stacks.
   123→	domains := make(map[string]string) // domain -> "app:name" or "stack:name"
   124→
   125→	for _, name := range slices.Sorted(maps.Keys(cfg.Apps)) {
   126→		app := cfg.Apps[name]
   127→		if app.Repo == "" {
   128→			return fmt.Errorf("app %q: repo is required", name)
   129→		}
   130→		if app.Domain == "" {
   131→			return fmt.Errorf("app %q: domain is required", name)
   132→		}
   133→		if prev, exists := domains[app.Domain]; exists {
   134→			return fmt.Errorf("app %q: domain %q already used by %s", name, app.Domain, prev)
   135→		}
   136→		domains[app.Domain] = "app:" + name
   137→
   138→		for i, sec := range app.Secrets {
   139→			if sec.Type != "env" && sec.Type != "docker-secret" {
   140→				return fmt.Errorf("app %q: secrets[%d]: type must be \"env\" or \"docker-secret\", got %q", name, i, sec.Type)
   141→			}
   142→		}
   143→
   144→		if app.Preview != nil && app.Preview.Enabled {
   145→			if app.Preview.Domain == "" {
   146→				return fmt.Errorf("app %q: preview.domain is required when preview.enabled is true", name)
   147→			}
   148→			if !strings.Contains(app.Preview.Domain, "*") {
   149→				return fmt.Errorf("app %q: preview.domain must contain a wildcard (*)", name)
   150→			}
   151→		}
   152→	}
   153→
   154→	for _, name := range slices.Sorted(maps.Keys(cfg.Stacks)) {
   155→		stack := cfg.Stacks[name]
   156→		if stack.Path == "" {
   157→			return fmt.Errorf("stack %q: path is required", name)
   158→		}
   159→		if stack.Domain == "" {
   160→			return fmt.Errorf("stack %q: domain is required", name)
   161→		}
   162→		if prev, exists := domains[stack.Domain]; exists {
   163→			return fmt.Errorf("stack %q: domain %q already used by %s", name, stack.Domain, prev)
   164→		}
   165→		domains[stack.Domain] = "stack:" + name
   166→	}
   167→
   168→	return nil
   169→}
   170→

