     1→package secrets
     2→
     3→import (
     4→	"bytes"
     5→	"encoding/json"
     6→	"errors"
     7→	"fmt"
     8→	"log/slog"
     9→	"os"
    10→	"path/filepath"
    11→	"slices"
    12→	"strings"
    13→	"syscall"
    14→
    15→	"filippo.io/age"
    16→	"github.com/nogo/herald/internal/config"
    17→)
    18→
    19→// Store manages an age-encrypted secrets file.
    20→type Store struct {
    21→	keyPath     string // path to age.key
    22→	secretsPath string // path to secrets.age
    23→}
    24→
    25→// NewStore creates a Store rooted at dataDir.
    26→func NewStore(dataDir string) *Store {
    27→	return &Store{
    28→		keyPath:     filepath.Join(dataDir, "age.key"),
    29→		secretsPath: filepath.Join(dataDir, "secrets.age"),
    30→	}
    31→}
    32→
    33→// Init generates the age key if it doesn't exist. If the key file has
    34→// wrong permissions it fixes them and logs a warning.
    35→func (s *Store) Init() error {
    36→	info, err := os.Stat(s.keyPath)
    37→	if err == nil {
    38→		if info.Mode().Perm() != 0600 {
    39→			slog.Warn("age key has insecure permissions, fixing", "path", s.keyPath, "mode", info.Mode().Perm())
    40→			if err := os.Chmod(s.keyPath, 0600); err != nil {
    41→				return fmt.Errorf("fixing age key permissions: %w", err)
    42→			}
    43→		}
    44→		return nil
    45→	}
    46→	if !errors.Is(err, os.ErrNotExist) {
    47→		return fmt.Errorf("checking age key %s: %w", s.keyPath, err)
    48→	}
    49→
    50→	if err := os.MkdirAll(filepath.Dir(s.keyPath), 0700); err != nil {
    51→		return fmt.Errorf("creating data directory: %w", err)
    52→	}
    53→
    54→	identity, err := age.GenerateX25519Identity()
    55→	if err != nil {
    56→		return fmt.Errorf("generating age key: %w", err)
    57→	}
    58→
    59→	// O_EXCL prevents overwriting if two processes race to init.
    60→	f, err := os.OpenFile(s.keyPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
    61→	if err != nil {
    62→		return fmt.Errorf("creating age key file: %w", err)
    63→	}
    64→	defer f.Close()
    65→
    66→	if _, err := fmt.Fprintln(f, identity.String()); err != nil {
    67→		return fmt.Errorf("writing age key: %w", err)
    68→	}
    69→	return nil
    70→}
    71→
    72→func (s *Store) loadIdentity() (*age.X25519Identity, error) {
    73→	data, err := os.ReadFile(s.keyPath)
    74→	if err != nil {
    75→		return nil, fmt.Errorf("reading age key %s: %w", s.keyPath, err)
    76→	}
    77→	identity, err := age.ParseX25519Identity(strings.TrimSpace(string(data)))
    78→	if err != nil {
    79→		return nil, fmt.Errorf("parsing age key: %w", err)
    80→	}
    81→	return identity, nil
    82→}
    83→
    84→// withLock acquires an exclusive flock on a lock file for the duration of fn.
    85→func (s *Store) withLock(fn func() error) error {
    86→	lockPath := s.secretsPath + ".lock"
    87→	lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0600)
    88→	if err != nil {
    89→		return fmt.Errorf("opening lock file: %w", err)
    90→	}
    91→	defer lf.Close()
    92→
    93→	if err := syscall.Flock(int(lf.Fd()), syscall.LOCK_EX); err != nil {
    94→		return fmt.Errorf("acquiring secrets lock: %w", err)
    95→	}
    96→	defer syscall.Flock(int(lf.Fd()), syscall.LOCK_UN) //nolint:errcheck
    97→
    98→	return fn()
    99→}
   100→
   101→func (s *Store) readSecrets() (map[string]string, error) {
   102→	data, err := os.ReadFile(s.secretsPath)
   103→	if errors.Is(err, os.ErrNotExist) {
   104→		return make(map[string]string), nil
   105→	}
   106→	if err != nil {
   107→		return nil, fmt.Errorf("reading secrets file: %w", err)
   108→	}
   109→
   110→	identity, err := s.loadIdentity()
   111→	if err != nil {
   112→		return nil, err
   113→	}
   114→
   115→	r, err := age.Decrypt(bytes.NewReader(data), identity)
   116→	if err != nil {
   117→		return nil, fmt.Errorf("cannot decrypt secrets store: %w. Is the age key correct?", err)
   118→	}
   119→
   120→	var secrets map[string]string
   121→	if err := json.NewDecoder(r).Decode(&secrets); err != nil {
   122→		return nil, fmt.Errorf("decoding secrets: %w", err)
   123→	}
   124→	return secrets, nil
   125→}
   126→
   127→func (s *Store) writeSecrets(secrets map[string]string) error {
   128→	identity, err := s.loadIdentity()
   129→	if err != nil {
   130→		return err
   131→	}
   132→
   133→	jsonData, err := json.Marshal(secrets)
   134→	if err != nil {
   135→		return fmt.Errorf("encoding secrets: %w", err)
   136→	}
   137→
   138→	tmpPath := s.secretsPath + ".tmp"
   139→	f, err := os.OpenFile(tmpPath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
   140→	if err != nil {
   141→		return fmt.Errorf("creating temp secrets file: %w", err)
   142→	}
   143→
   144→	w, err := age.Encrypt(f, identity.Recipient())
   145→	if err != nil {
   146→		f.Close()
   147→		os.Remove(tmpPath)
   148→		return fmt.Errorf("initializing encryption: %w", err)
   149→	}
   150→
   151→	if _, err := w.Write(jsonData); err != nil {
   152→		f.Close()
   153→		os.Remove(tmpPath)
   154→		return fmt.Errorf("writing encrypted data: %w", err)
   155→	}
   156→
   157→	if err := w.Close(); err != nil {
   158→		f.Close()
   159→		os.Remove(tmpPath)
   160→		return fmt.Errorf("finalizing encryption: %w", err)
   161→	}
   162→
   163→	if err := f.Close(); err != nil {
   164→		os.Remove(tmpPath)
   165→		return fmt.Errorf("closing temp file: %w", err)
   166→	}
   167→
   168→	return os.Rename(tmpPath, s.secretsPath)
   169→}
   170→
   171→// Set adds or updates a secret.
   172→func (s *Store) Set(key, value string) error {
   173→	return s.withLock(func() error {
   174→		secrets, err := s.readSecrets()
   175→		if err != nil {
   176→			return err
   177→		}
   178→		secrets[key] = value
   179→		return s.writeSecrets(secrets)
   180→	})
   181→}
   182→
   183→// Get retrieves a secret value by key.
   184→func (s *Store) Get(key string) (string, error) {
   185→	secrets, err := s.readSecrets()
   186→	if err != nil {
   187→		return "", err
   188→	}
   189→	val, ok := secrets[key]
   190→	if !ok {
   191→		return "", fmt.Errorf("secret '%s' not found in store", key)
   192→	}
   193→	return val, nil
   194→}
   195→
   196→// List returns all secret keys sorted alphabetically.
   197→func (s *Store) List() ([]string, error) {
   198→	secrets, err := s.readSecrets()
   199→	if err != nil {
   200→		return nil, err
   201→	}
   202→	keys := make([]string, 0, len(secrets))
   203→	for k := range secrets {
   204→		keys = append(keys, k)
   205→	}
   206→	slices.Sort(keys)
   207→	return keys, nil
   208→}
   209→
   210→// Delete removes a secret. Returns an error if the key doesn't exist.
   211→func (s *Store) Delete(key string) error {
   212→	return s.withLock(func() error {
   213→		secrets, err := s.readSecrets()
   214→		if err != nil {
   215→			return err
   216→		}
   217→		if _, ok := secrets[key]; !ok {
   218→			return fmt.Errorf("secret '%s' not found in store", key)
   219→		}
   220→		delete(secrets, key)
   221→		return s.writeSecrets(secrets)
   222→	})
   223→}
   224→
   225→// Import reads filePath and stores its contents as a secret.
   226→func (s *Store) Import(key, filePath string) error {
   227→	data, err := os.ReadFile(filePath)
   228→	if err != nil {
   229→		return fmt.Errorf("reading file %s: %w", filePath, err)
   230→	}
   231→	return s.Set(key, string(data))
   232→}
   233→
   234→// Resolve maps a list of SecretRefs to environment variables and Docker secret
   235→// values. Returns an error if any referenced key is missing.
   236→func (s *Store) Resolve(refs []config.SecretRef) (envVars map[string]string, dockerSecrets map[string]string, err error) {
   237→	secrets, err := s.readSecrets()
   238→	if err != nil {
   239→		return nil, nil, err
   240→	}
   241→
   242→	envVars = make(map[string]string)
   243→	dockerSecrets = make(map[string]string)
   244→
   245→	for _, ref := range refs {
   246→		val, ok := secrets[ref.Key]
   247→		if !ok {
   248→			return nil, nil, fmt.Errorf("secret '%s' not found in store", ref.Key)
   249→		}
   250→		switch ref.Type {
   251→		case "env":
   252→			envVars[ref.Target] = val
   253→		case "docker-secret":
   254→			dockerSecrets[ref.Target] = val
   255→		}
   256→	}
   257→
   258→	return envVars, dockerSecrets, nil
   259→}
   260→

