     1→package caddy
     2→
     3→import (
     4→	"bytes"
     5→	"context"
     6→	"encoding/json"
     7→	"fmt"
     8→	"log/slog"
     9→	"os"
    10→	"os/exec"
    11→	"path/filepath"
    12→	"regexp"
    13→	"strings"
    14→	"time"
    15→
    16→	"github.com/nogo/herald/internal/config"
    17→)
    18→
    19→const (
    20→	caddyNetwork       = "caddy"
    21→	caddyContainerName = "herald-caddy"
    22→)
    23→
    24→// CaddyManager manages the Caddy reverse proxy lifecycle.
    25→type CaddyManager struct {
    26→	Config     *config.Config
    27→	Logger     *slog.Logger
    28→	HeraldPort int
    29→}
    30→
    31→// CaddyStatus holds the current state of Caddy and its proxied domains.
    32→type CaddyStatus struct {
    33→	Running bool
    34→	Uptime  string
    35→	Email   string
    36→	Domains []ProxiedDomain
    37→}
    38→
    39→// ProxiedDomain represents a domain being proxied by Caddy.
    40→type ProxiedDomain struct {
    41→	Domain   string
    42→	Upstream string
    43→}
    44→
    45→func (m *CaddyManager) composeFilePath() string {
    46→	return filepath.Join(m.Config.Server.StacksDir, "caddy", "compose.yml")
    47→}
    48→
    49→// EnsureNetwork creates the caddy Docker network if it doesn't exist.
    50→func (m *CaddyManager) EnsureNetwork(ctx context.Context) error {
    51→	cmd := exec.CommandContext(ctx, "docker", "network", "inspect", caddyNetwork)
    52→	if err := cmd.Run(); err == nil {
    53→		return nil
    54→	}
    55→	return runCmd(ctx, m.Logger, "docker", "network", "create", caddyNetwork)
    56→}
    57→
    58→// Start ensures the network exists, writes the compose file, and starts Caddy.
    59→func (m *CaddyManager) Start(ctx context.Context) error {
    60→	if err := m.EnsureNetwork(ctx); err != nil {
    61→		return fmt.Errorf("ensuring caddy network: %w", err)
    62→	}
    63→
    64→	composePath := m.composeFilePath()
    65→	if err := os.MkdirAll(filepath.Dir(composePath), 0755); err != nil {
    66→		return fmt.Errorf("creating caddy dir: %w", err)
    67→	}
    68→
    69→	content := generateComposeContent(m.Config.Server.AcmeEmail, m.Config.Server.DeployDomain, m.HeraldPort)
    70→	if err := os.WriteFile(composePath, []byte(content), 0644); err != nil {
    71→		return fmt.Errorf("writing compose file: %w", err)
    72→	}
    73→
    74→	err := runCmd(ctx, m.Logger, "docker", "compose", "-f", composePath, "-p", "herald-caddy", "up", "-d")
    75→	if err != nil {
    76→		if strings.Contains(err.Error(), "address already in use") {
    77→			return fmt.Errorf("ports 80/443 are in use. Stop the existing proxy (nginx-proxy?) before starting Caddy")
    78→		}
    79→		return err
    80→	}
    81→
    82→	deadline := time.Now().Add(30 * time.Second)
    83→	for time.Now().Before(deadline) {
    84→		if running, _ := m.IsRunning(ctx); running {
    85→			break
    86→		}
    87→		time.Sleep(2 * time.Second)
    88→	}
    89→
    90→	fmt.Printf("caddy started on :80/:443, ACME email: %s\n", m.Config.Server.AcmeEmail)
    91→	return nil
    92→}
    93→
    94→// Stop tears down the Caddy compose stack without removing the network or volumes.
    95→func (m *CaddyManager) Stop(ctx context.Context) error {
    96→	composePath := m.composeFilePath()
    97→	if err := runCmd(ctx, m.Logger, "docker", "compose", "-f", composePath, "-p", "herald-caddy", "down"); err != nil {
    98→		return err
    99→	}
   100→	fmt.Println("caddy stopped")
   101→	return nil
   102→}
   103→
   104→// IsRunning reports whether the herald-caddy container is running.
   105→func (m *CaddyManager) IsRunning(ctx context.Context) (bool, error) {
   106→	out, err := runCmdOutput(ctx, "docker", "ps", "-q", "--filter", "name=herald-caddy", "--filter", "status=running")
   107→	if err != nil {
   108→		return false, err
   109→	}
   110→	return strings.TrimSpace(out) != "", nil
   111→}
   112→
   113→// Status returns the current Caddy state and proxied domain list.
   114→func (m *CaddyManager) Status(ctx context.Context) (*CaddyStatus, error) {
   115→	s := &CaddyStatus{Email: m.Config.Server.AcmeEmail}
   116→
   117→	running, err := m.IsRunning(ctx)
   118→	if err != nil {
   119→		return nil, fmt.Errorf("checking running state: %w", err)
   120→	}
   121→	s.Running = running
   122→
   123→	if running {
   124→		out, err := runCmdOutput(ctx, "docker", "inspect", "--format", "{{.State.StartedAt}}", caddyContainerName)
   125→		if err == nil {
   126→			s.Uptime = formatUptime(strings.TrimSpace(out))
   127→		}
   128→	}
   129→
   130→	domains, err := m.listProxiedDomains(ctx)
   131→	if err != nil {
   132→		m.Logger.Warn("could not list proxied domains", "error", err)
   133→	}
   134→	s.Domains = domains
   135→
   136→	return s, nil
   137→}
   138→
   139→func (m *CaddyManager) listProxiedDomains(ctx context.Context) ([]ProxiedDomain, error) {
