   197→func formatUptime(startedAt string) string {
   198→	t, err := time.Parse(time.RFC3339Nano, startedAt)
   199→	if err != nil {
   200→		return "unknown"
   201→	}
   202→	d := time.Since(t)
   203→	switch {
   204→	case d >= 24*time.Hour:
   205→		days := int(d.Hours() / 24)
   206→		if days == 1 {
   207→			return "1 day"
   208→		}
   209→		return fmt.Sprintf("%d days", days)
   210→	case d >= time.Hour:
   211→		hours := int(d.Hours())
   212→		if hours == 1 {
   213→			return "1 hour"
   214→		}
   215→		return fmt.Sprintf("%d hours", hours)
   216→	default:
   217→		mins := int(d.Minutes())
   218→		if mins <= 1 {
   219→			return "1 minute"
   220→		}
   221→		return fmt.Sprintf("%d minutes", mins)
   222→	}
   223→}
