   164→// gitSync clones the repo on first deploy or fetch+reset on subsequent ones.
   165→func (d *Deployer) gitSync(ctx context.Context, appDir string, app config.App) error {
   166→	repoDir := filepath.Join(appDir, "repo")
   167→	cloneURL := buildCloneURL(d.Config.Server.GithubToken, app.Repo)
   168→
   169→	_, err := os.Stat(repoDir)
   170→	if os.IsNotExist(err) {
   171→		d.Logger.Info("git clone", "repo", app.Repo, "branch", app.Branch)
   172→		return runCmd(ctx, d.Logger, "", "git",
   173→			"clone", "--branch", app.Branch,
   174→			"--single-branch", "--depth", "1",
   175→			cloneURL, repoDir,
   176→		)
   177→	}
   178→	if err != nil {
   179→		return fmt.Errorf("stat repo dir: %w", err)
   180→	}
   181→
   182→	d.Logger.Info("git fetch+reset", "repo", app.Repo, "branch", app.Branch)
   183→	if err := runCmd(ctx, d.Logger, repoDir, "git", "fetch", "origin", app.Branch); err != nil {
   184→		return err
   185→	}
   186→	return runCmd(ctx, d.Logger, repoDir, "git", "reset", "--hard", "origin/"+app.Branch)
   187→}
