    93→func (c *GitHubClient) doRequest(ctx context.Context, method, url string, body any) (*http.Response, error) {
    94→	var bodyReader io.Reader
    95→	if body != nil {
    96→		data, err := json.Marshal(body)
    97→		if err != nil {
    98→			return nil, fmt.Errorf("marshaling request body: %w", err)
    99→		}
   100→		bodyReader = bytes.NewReader(data)
   101→	}
   102→
   103→	req, err := http.NewRequestWithContext(ctx, method, url, bodyReader)
   104→	if err != nil {
   105→		return nil, fmt.Errorf("creating request: %w", err)
   106→	}
   107→
   108→	req.Header.Set("Authorization", "Bearer "+c.Token)
   109→	req.Header.Set("Accept", "application/vnd.github+json")
   110→	req.Header.Set("User-Agent", userAgent)
   111→	if body != nil {
   112→		req.Header.Set("Content-Type", "application/json")
   113→	}
   114→
   115→	resp, err := c.HTTP.Do(req)
   116→	if err != nil {
   117→		return nil, fmt.Errorf("executing request: %w", err)
   118→	}
   119→
   120→	// Check for rate limiting before returning.
   121→	if resp.StatusCode == http.StatusForbidden && resp.Header.Get("X-RateLimit-Remaining") == "0" {
   122→		resetTime := parseUnixTimestamp(resp.Header.Get("X-RateLimit-Reset"))
   123→		c.Logger.Warn("GitHub API rate limit exceeded", "reset_at", resetTime)
   124→		resp.Body.Close()
   125→		return nil, fmt.Errorf("GitHub API rate limit exceeded, resets at %s", resetTime)
   126→	}
   127→
   128→	return resp, nil
   129→}
   130→
   131→func parseUnixTimestamp(s string) string {
   132→	ts, err := strconv.ParseInt(s, 10, 64)
   133→	if err != nil {
   134→		return s
   135→	}
   136→	return time.Unix(ts, 0).UTC().Format(time.RFC3339)
   137→}
