   292→// SyncWebhooks ensures herald webhooks are registered on all repos referenced in config.
   293→func SyncWebhooks(ctx context.Context, cfg *config.Config, store *secrets.Store, client *GitHubClient) ([]SyncResult, error) {
   294→	webhookSecret, err := store.Get("herald/webhook_secret")
   295→	if err != nil {
   296→		return nil, fmt.Errorf("getting webhook secret: %w", err)
   297→	}
   298→
   299→	targetURL := webhookURL(cfg)
   300→	repos := uniqueRepos(cfg)
   301→	slices.Sort(repos)
   302→
   303→	results := make([]SyncResult, 0, len(repos))
   304→	for _, repoFull := range repos {
   305→		results = append(results, syncRepo(ctx, cfg, client, repoFull, targetURL, webhookSecret))
   306→	}
   307→
   308→	return results, nil
   309→}
   310→
   311→func syncRepo(ctx context.Context, cfg *config.Config, client *GitHubClient, repoFull, targetURL, webhookSecret string) SyncResult {
   312→	result := SyncResult{Repo: repoFull}
   313→
   314→	owner, repoName, err := splitRepo(repoFull)
   315→	if err != nil {
   316→		result.Action = "error"
   317→		result.Error = err
   318→		return result
   319→	}
   320→
   321→	hooks, err := client.ListWebhooks(ctx, owner, repoName)
   322→	if err != nil {
   323→		result.Action = "error"
   324→		result.Error = formatAPIError(repoFull, err)
   325→		return result
   326→	}
   327→
   328→	var heraldHook *Webhook
   329→	for i := range hooks {
   330→		if hooks[i].Config.URL == targetURL {
   331→			heraldHook = &hooks[i]
   332→			break
   333→		}
   334→	}
   335→
   336→	if heraldHook != nil && heraldHook.Active {
   337→		result.Action = "exists"
   338→		result.ID = heraldHook.ID
   339→		return result
   340→	}
   341→
   342→	// Delete inactive hook before recreating.
   343→	if heraldHook != nil {
   344→		if err := client.DeleteWebhook(ctx, owner, repoName, heraldHook.ID); err != nil {
   345→			result.Action = "error"
   346→			result.Error = formatAPIError(repoFull, err)
   347→			return result
   348→		}
   349→	}
   350→
   351→	hook, err := client.CreateWebhook(ctx, owner, repoName, CreateWebhookRequest{
   352→		URL:    targetURL,
   353→		Secret: webhookSecret,
   354→		Events: eventsForRepo(cfg, repoFull),
   355→	})
   356→	if err != nil {
   357→		result.Action = "error"
   358→		result.Error = formatAPIError(repoFull, err)
   359→		return result
   360→	}
   361→
   362→	result.Action = "created"
   363→	result.ID = hook.ID
   364→	return result
   365→}
   366→
   367→// ListWebhookStatuses returns the webhook status for each unique repo in config.
   368→func ListWebhookStatuses(ctx context.Context, cfg *config.Config, client *GitHubClient) []WebhookStatus {
   369→	targetURL := webhookURL(cfg)
   370→	repos := uniqueRepos(cfg)
   371→	slices.Sort(repos)
   372→
   373→	statuses := make([]WebhookStatus, 0, len(repos))
   374→	for _, repoFull := range repos {
   375→		status := WebhookStatus{Repo: repoFull}
   376→
   377→		owner, repoName, err := splitRepo(repoFull)
   378→		if err != nil {
   379→			statuses = append(statuses, status)
   380→			continue
   381→		}
   382→
   383→		hooks, err := client.ListWebhooks(ctx, owner, repoName)
   384→		if err != nil {
   385→			statuses = append(statuses, status)
   386→			continue
   387→		}
   388→
   389→		for _, hook := range hooks {
   390→			if hook.Config.URL == targetURL {
   391→				status.Found = true
   392→				status.URL = hook.Config.URL
   393→				status.Active = hook.Active
   394→				break
   395→			}
   396→		}
   397→
   398→		statuses = append(statuses, status)
   399→	}
   400→
   401→	return statuses
   402→}
