   287→// isGitHubError is a helper to unwrap *GitHubError from an error chain.
   288→func isGitHubError(err error, target **GitHubError) bool {
   289→	var ghErr *GitHubError
   290→	if ok := (func() bool {
   291→		for {
   292→			if e, ok2 := err.(*GitHubError); ok2 {
   293→				ghErr = e
   294→				return true
   295→			}
   296→			type unwrapper interface{ Unwrap() error }
   297→			u, ok2 := err.(unwrapper)
   298→			if !ok2 {
   299→				return false
   300→			}
   301→			err = u.Unwrap()
   302→		}
   303→	})(); ok {
   304→		*target = ghErr
   305→		return true
   306→	}
   307→	return false
   308→}
