package cmd

import (
	"context"
	"fmt"
	"log/slog"
	"maps"
	"os"
	"slices"
	"strings"

	"github.com/nogo/herald/internal/deployer"
	"github.com/nogo/herald/internal/secrets"
	"github.com/spf13/cobra"
)

var deployCmd = &cobra.Command{
	Use:   "deploy [app]",
	Short: "Force re-deploy an app",
	RunE: func(cmd *cobra.Command, args []string) error {
		cmd.SilenceUsage = true

		if len(args) == 0 {
			names := slices.Sorted(maps.Keys(Cfg.Apps))
			if len(names) == 0 {
				fmt.Fprintln(cmd.OutOrStdout(), "No apps configured.")
				return nil
			}
			fmt.Fprintln(cmd.OutOrStdout(), "Available apps:")
			for _, name := range names {
				fmt.Fprintf(cmd.OutOrStdout(), "  %s\n", name)
			}
			return nil
		}

		appName := args[0]
		if _, ok := Cfg.Apps[appName]; !ok {
			names := slices.Sorted(maps.Keys(Cfg.Apps))
			return fmt.Errorf("app %q not found. Available: %s", appName, strings.Join(names, ", "))
		}

		store := secrets.NewStore(dataDir)
		d := &deployer.Deployer{
			Config:  Cfg,
			Secrets: store,
			Logger:  slog.Default(),
		}

		if err := d.Deploy(context.Background(), appName); err != nil {
			fmt.Fprintf(os.Stderr, "deploy %s: failed: %v\n", appName, err)
			os.Exit(1)
		}

		fmt.Fprintf(cmd.OutOrStdout(), "deploy %s: success\n", appName)
		return nil
	},
}

func init() {
	rootCmd.AddCommand(deployCmd)
}

package cmd

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/nogo/herald/internal/deployer"
	"github.com/nogo/herald/internal/secrets"
	"github.com/nogo/herald/internal/webhook"
	"github.com/spf13/cobra"
)

var port int

var serveCmd = &cobra.Command{
	Use:   "serve",
	Short: "Start webhook listener and deploy daemon",
	RunE: func(cmd *cobra.Command, args []string) error {
		store := secrets.NewStore(dataDir)
		secret, err := store.Get("herald/webhook_secret")
		if err != nil {
			return fmt.Errorf("webhook secret not configured. Run: herald secret set herald/webhook_secret <your-secret>")
		}

		d := &deployer.Deployer{
			Config:  Cfg,
			Secrets: store,
			Logger:  slog.Default(),
		}

		srv := &webhook.Server{
			Config:  Cfg,
			Secret:  secret,
			Verbose: verbose,
			OnDeploy: func(req webhook.DeployRequest) {
				d.DeployAsync(req.AppName)
			},
		}

		addr := fmt.Sprintf(":%d", port)
		httpSrv := &http.Server{
			Addr:    addr,
			Handler: srv.Handler(),
		}

		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
		defer stop()

		go func() {
			slog.Info("herald server started", "addr", addr)
			if err := httpSrv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
				slog.Error("server error", "error", err)
				stop()
			}
		}()

		<-ctx.Done()
		stop()

		if cause := context.Cause(ctx); cause != nil {
			slog.Info("herald server stopping", "cause", cause)
		}

		shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()

		if err := httpSrv.Shutdown(shutdownCtx); err != nil {
			return fmt.Errorf("server shutdown: %w", err)
		}

		d.Wait()
		slog.Info("herald server stopped")
		return nil
	},
}

func init() {
	rootCmd.AddCommand(serveCmd)
	serveCmd.Flags().IntVar(&port, "port", 8080, "Port to listen on")
}

